const { createHmac } = require('crypto');
const path = '/internal/calendar/notifications/validate';
const headers = $json.headers || {};
const body = { channelId: headers['x-goog-channel-id'], resourceId: headers['x-goog-resource-id'], messageNumber: headers['x-goog-message-number'] };
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];

const { createHmac } = require('crypto');
const path = '/internal/calendar/provider/changes';
const checkpoint = $json.pageToken || $json.syncToken || 'full-resync';
const body = { connectionId: $json.connectionId, checkpoint };
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];

const { createHmac } = require('crypto');
const path = '/internal/calendar/sync/reset';
const signal = $('Validate Channel And Claim Signal').item.json;
const body = { operationId: `${signal.signalId}:reset`, tenantId: signal.tenantId, ownerId: signal.ownerId, connectionId: signal.connectionId };
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];

const signal = $('Validate Channel And Claim Signal').item.json;
const payload = $json.body ?? {};
const page = typeof payload === 'string' ? JSON.parse(payload) : payload;
const commands = [];
if (page.resetRequired) commands.push({ operationId: `${signal.signalId}:reset`, tenantId: signal.tenantId, ownerId: signal.ownerId, connectionId: signal.connectionId, kind: 'sync_token_gone' });
for (const event of (page.events || [])) {
  const base = { operationId: `${signal.signalId}:event:${event.id}:${event.etag}`, tenantId: signal.tenantId, ownerId: signal.ownerId, connectionId: signal.connectionId, providerEventId: event.id, providerEtag: event.etag };
  if (event.status === 'cancelled') commands.push({ ...base, kind: 'event_deleted' });
  else if (event.start && event.start.dateTime) commands.push({ ...base, kind: 'event_changed', title: event.summary || '', dueAt: event.start.dateTime, timeZone: event.start.timeZone || 'UTC' });
}
const token = page.nextPageToken || page.nextSyncToken;
if (token) commands.push({ operationId: `${signal.signalId}:checkpoint:${token}`, tenantId: signal.tenantId, ownerId: signal.ownerId, connectionId: signal.connectionId, kind: 'sync_checkpoint', ...(page.nextPageToken ? { nextPageToken: page.nextPageToken } : {}), ...(page.nextSyncToken ? { nextSyncToken: page.nextSyncToken } : {}) });
return commands.map(command => ({ json: { command } }));

const { createHmac } = require('crypto');
const path = '/internal/calendar/sync/apply';
const body = $json.command;
const rawBody = JSON.stringify(body);
const timestamp = String(Math.floor(Date.now() / 1000));
const signedSignature = createHmac('sha256', $env.CALENDAR_INTERNAL_HMAC_KEY).update(`v1\n${timestamp}\nPOST\n${path}\n${rawBody}`).digest('hex');
return [{ json: { signedBody: rawBody, signedTimestamp: timestamp, signedSignature } }];
